export scenario book(type:Type,customer:Customer,contact:Contact,from:datetime label=label_Window_from) by=authenticated label="Book appointment"@{nl="Afspraak boeken"}
 require type.parent.active and type.parent.host.active and from>=now and contact.parent==customer
 require (contact.account==actor and contact.verified) or (host_manager and can_work(actor,type.parent.location))
 require any(type.parent.Window as window,window.available and window.from<=from and from+type.duration<=window.until)
 do
  create Appointment {parent=type,customer,contact,from,until=from+type.duration,duration=type.duration,source=operation.id,host=type.parent.host.user} as appointment
  send StaffSchedule.reserve {value={source=appointment.source,employee=appointment.host,location=type.parent.location.id,from,until=appointment.until,skill="host",kind=appointment,revision=appointment.version}} as host_hold
  set appointment {host_delivery=host_hold.id}
  if type.room!=null
   send Rooms.hold {value={source=appointment.source,resource=type.room,customer=customer.id,account=actor,from,until=appointment.until,quantity=1}} as room_hold
   set appointment {room_delivery=room_hold.id}
  else
   set appointment {room_ok=true}
# Cancel an owned appointment before its cutoff or by an attributed host action. @{nl="Annuleer een eigen afspraak vóór de annuleringsgrens of via een toegeschreven gastheeractie."}
export scenario cancel(appointment:Appointment,reason:text) by=authenticated or host_manager
 require appointment.state in [pending,confirmed] and trim(reason)!=""
 require (appointment.contact.account==actor and appointment.contact.verified and now<appointment.from-appointment.parent.parent.cutoff) or (host_manager and can_work(actor,appointment.parent.parent.location))
 do
  set appointment {state=cancelled,reason}
  cancel appointment.id
  send StaffSchedule.release {source=appointment.source,revision=appointment.version} as host_release
  if appointment.parent.room!=null
   send Rooms.release {source=appointment.source,reason} as room_release
 examples seed=[test_worker] appointment=booked reason="Changed plans"
  as,appointment.state -> appointment.state
  members,confirmed -> cancelled
  members,cancelled -> error(rule_failed)
  public,confirmed -> error(forbidden)

export capability ScheduleV1 version=1
 reserve(value:CommitmentRequest) -> OperationOutcome
 release(source:text,revision:int) -> OperationOutcome
 event changed { value:OperationOutcome }

scenario reserve_connected on=ScheduleRequests.reserve
 require event.employee.user==event.value.employee and event.location.id==event.value.location and event.employee.active and event.value.from<event.value.until
 require can_work(event.employee.user,event.location) and (event.value.kind==absence or event.value.skill in event.employee.skills)
 do
  let previous=first(event.roster.Commitment as item where item.source==event.value.source order=item.id)
  if previous!=null and previous.revision>=event.value.revision
   require previous.revision==event.value.revision and previous.employee==event.employee and previous.from==event.value.from and previous.until==event.value.until
   emit ReservationOutcome {value={source=previous.source,revision=previous.revision,state=confirmed,reference=previous.id}}
  else
   let conflicts=event.roster.Commitment as item where item!=previous and item.active and item.employee==event.employee and overlaps(event.value.from-event.value.before,event.value.until+event.value.after,item.from-item.before,item.until+item.after)
   let available=any(event.roster.Availability as window,window.employee==event.employee and window.available and window.from<=event.value.from-event.value.before and event.value.until+event.value.after<=window.until) and not any(event.roster.Availability as window,window.employee==event.employee and not window.available and overlaps(event.value.from,event.value.until,window.from,window.until))
   let compatible=all(conflicts as item,item.kind==duty and item.location==event.location and item.from<=event.value.from and event.value.until<=item.until and event.value.kind in [visit,appointment,interview])
   if event.value.kind!=absence and (not available or not compatible)
    emit ReservationOutcome {value={source=event.value.source,revision=event.value.revision,state=unavailable,detail="Employee commitment unavailable"}}
   else
    if previous==null
     create Commitment {parent=event.roster,employee=event.employee,location=event.location,from=event.value.from,until=event.value.until,before=event.value.before,after=event.value.after,skill=event.value.skill,kind=event.value.kind,source=event.value.source,revision=event.value.revision} as commitment
     emit ReservationOutcome {value={source=commitment.source,revision=commitment.revision,state=confirmed,reference=commitment.id}}
    else
     set previous {employee=event.employee,location=event.location,from=event.value.from,until=event.value.until,before=event.value.before,after=event.value.after,skill=event.value.skill,kind=event.value.kind,revision=event.value.revision,active=true}
     emit ReservationOutcome {value={source=previous.source,revision=event.value.revision,state=confirmed,reference=previous.id}}
    if event.value.kind==absence
     for conflict in conflicts limit=100
      set conflict {conflict=true}
scenario release_connected on=ScheduleRequests.release
 do
  for commitment in event.roster.Commitment as item where item.source==event.source and item.active limit=1
   require event.revision>=commitment.revision
   set commitment {active=false}
   emit ReservationOutcome {value={source=commitment.source,revision=event.revision,state=released,reference=commitment.id}}

export contract RoomRequest { source:text label=label_RoomRequest_source, resource:text label="Resource reference"@{nl="Voorzieningsreferentie"}, customer:text label="Customer reference"@{nl="Klantreferentie"}, account:user label=label_RoomRequest_account, from:datetime label=label_RoomRequest_from, until:datetime label=label_RoomRequest_until, quantity:int, price:money?, terms:text? label=label_RoomRequest_terms } label="Workspace request"@{nl="Werkplekaanvraag"}
export capability RoomsV1 version=1
 hold(value:RoomRequest) -> OperationOutcome
 confirm(source:text) -> OperationOutcome
 move(value:RoomRequest) -> OperationOutcome
 release(source:text,reason:text) -> OperationOutcome
 downtime(source:text,resource:text,from:datetime,until:datetime?) -> OperationOutcome
 restore(source:text,evidence:text) -> OperationOutcome
 event changed { value:OperationOutcome }
